<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {useRoute} from 'vue-router';
import {managementRequest} from '../api/management';
type Case={id:string;cycle_id:string;month:string;target_name:string;department_name:string|null;reason_code:string;status:string;created_at:string;invalidated_at?:string|null};
type Action={action:string;reason:string;actor_name:string|null;created_at:string};
const route=useRoute(),items=ref<Case[]>([]),cycles=ref<any[]>([]),cycleId=ref(''),error=ref(''),loading=ref(false),busy=ref(false),reason=ref(''),selected=ref<Case|null>(null),history=ref<Action[]>([]),tab=ref<'open'|'done'>('open'),search=ref(''),type=ref(''),dept=ref(''),page=ref(1),rulesOpen=ref(false);
const preview=computed(()=>['localhost','127.0.0.1'].includes(location.hostname)&&route.query.preview==='exceptions');
const labels:Record<string,string>={HIGH_TOTAL:'高分核验',EXCELLENT:'重点高分核验',LOW_SCORE:'低分核验',HIGH_RATIO:'高分比例核验',MISSING_REASON:'理由不完整',SELF_PEER_DIFF:'自他评差异',MANUAL_FLAG:'人工标记'};
const actions:Record<string,string>={CONFIRM:'核验通过',DISMISS:'关闭核验项',REQUEST_SUPPLEMENT:'退回补充',SUGGEST_REVISION:'建议修订',REVISION_SUBMITTED:'已提交修订',VOID_REQUEST:'申请作废',VOID_APPROVE:'批准作废',VOID_REJECT:'驳回作废'};
const current=computed(()=>items.value.filter(i=>i.cycle_id===cycleId.value)),open=computed(()=>current.value.filter(i=>i.status==='OPEN'&&!i.invalidated_at)),done=computed(()=>current.value.filter(i=>!!i.invalidated_at||i.status==='RESOLVED'||i.status==='DISMISSED'));
const types=computed(()=>[...new Set(current.value.map(i=>i.reason_code))]),departments=computed(()=>[...new Set(current.value.map(i=>i.department_name).filter((x):x is string=>!!x))]);
const filtered=computed(()=>(tab.value==='open'?open.value:done.value).filter(i=>(!search.value||i.target_name.includes(search.value.trim()))&&(!type.value||i.reason_code===type.value)&&(!dept.value||i.department_name===dept.value)));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10))),visible=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10));
watch([tab,search,type,dept,cycleId],()=>page.value=1);
async function load(){loading.value=true;error.value='';try{if(preview.value){const demoCycle='preview-cycle';cycles.value=[{id:demoCycle,month:'2026-11',title:'【模拟】11 月月评',status:'CALIBRATING'}];cycleId.value=demoCycle;items.value=[['HIGH_TOTAL','模拟成员甲','产品部','OPEN'],['EXCELLENT','模拟成员乙','研发部','OPEN'],['LOW_SCORE','模拟成员丙','科技部','OPEN'],['SELF_PEER_DIFF','模拟成员丁','产品部','OPEN'],['MISSING_REASON','模拟成员戊','研发部','OPEN'],['HIGH_RATIO','模拟成员己','科技部','RESOLVED']].map(([reason_code,target_name,department_name,status],i)=>({id:`preview-${i}`,cycle_id:demoCycle,month:'2026-11',reason_code,target_name,department_name,status,created_at:'2026-11-05T10:00:00+08:00'}));return;}items.value=await managementRequest('management/exceptions');try{cycles.value=await managementRequest('management/dashboard');}catch{cycles.value=[...new Map(items.value.map(i=>[i.cycle_id,{id:i.cycle_id,month:i.month,title:i.month}])).values()];}if(!cycles.value.some(c=>c.id===cycleId.value))cycleId.value=String(route.query.cycleId??route.params.cycleId??(cycles.value.find(c=>c.status==='CALIBRATING')??cycles.value[0])?.id??'');}catch(e){error.value=e instanceof Error?e.message:'加载失败';}finally{loading.value=false;}}
async function show(item:Case){selected.value=item;history.value=[];reason.value='';error.value='';if(preview.value)return;try{history.value=await managementRequest('management/exception-history?caseId='+encodeURIComponent(item.id));}catch(e){error.value=e instanceof Error?e.message:'处理记录加载失败';}}
async function act(action:string){if(!selected.value||preview.value)return;busy.value=true;error.value='';try{await managementRequest(`calibration-cases/${selected.value.id}/actions`,{action,reason:reason.value});selected.value=null;await load();}catch(e){error.value=e instanceof Error?e.message:'提交失败';}finally{busy.value=false;}}
function selectStat(status:'open'|'done',code=''){tab.value=status;type.value=code;}
onMounted(load);
</script>
<template><div class="exceptions"><p v-if="preview" class="preview-notice" role="status">模拟数据预览：仅用于查看页面效果，不代表真实异常；处理操作已禁用。</p><div class="intro"><div><h2>异常核验</h2><p>处理本期评价中的业务异常，保留评分修订和反馈申诉各自的独立流程。</p></div><label>评价周期 <select v-model="cycleId"><option value="">请选择周期</option><option v-for="c in cycles" :key="c.id" :value="c.id">{{c.title}} · {{c.month}}</option></select></label></div><div class="stats"><button @click="selectStat('open')"><span>待核验</span><strong>{{open.length}}</strong></button><button @click="selectStat('open','HIGH_TOTAL')"><span>高分核验</span><strong>{{open.filter(i=>i.reason_code==='HIGH_TOTAL').length}}</strong></button><button @click="selectStat('open','EXCELLENT')"><span>重点高分核验</span><strong>{{open.filter(i=>i.reason_code==='EXCELLENT').length}}</strong></button><button @click="selectStat('open','LOW_SCORE')"><span>低分核验</span><strong>{{open.filter(i=>i.reason_code==='LOW_SCORE').length}}</strong></button><button @click="selectStat('done')"><span>已处理</span><strong>{{done.length}}</strong></button></div><section class="panel"><div class="bar"><div class="tabs"><button :class="{active:tab==='open'}" @click="tab='open'">待核验（{{open.length}}）</button><button :class="{active:tab==='done'}" @click="tab='done'">已处理（{{done.length}}）</button></div><button class="outline" @click="rulesOpen=true">异常规则说明</button></div><div class="filters"><input v-model="search" placeholder="搜索被评价人"><select v-model="type"><option value="">全部异常类型</option><option v-for="t in types" :key="t" :value="t">{{labels[t]??t}}</option></select><select v-model="dept"><option value="">全部部门</option><option v-for="d in departments" :key="d">{{d}}</option></select></div><p class="hint">仅显示您有权处理且与本人无利益冲突的记录；评价人身份和原始评分需另行授权。</p><p v-if="error" class="error" role="alert">{{error}} <button @click="load">重试</button></p><div class="scroll"><table><thead><tr><th>异常类型</th><th>被评价人</th><th>所属部门</th><th>状态</th><th>产生时间</th><th>操作</th></tr></thead><tbody><tr v-for="i in visible" :key="i.id"><td><span class="badge">{{labels[i.reason_code]??i.reason_code}}</span></td><td>{{i.target_name}}</td><td>{{i.department_name??'—'}}</td><td>{{i.invalidated_at?'已失效':i.status==='OPEN'?'待核验':i.status==='RESOLVED'?'已核验':'已关闭'}}</td><td>{{new Date(i.created_at).toLocaleString()}}</td><td><button @click="show(i)">{{i.status==='OPEN'?'核验 / 查看':'查看'}}</button></td></tr></tbody></table></div><p v-if="loading">加载中…</p><p v-else-if="!filtered.length">当前筛选条件下暂无异常记录。</p><div class="pagination">共 {{filtered.length}} 条 <button :disabled="page<=1" @click="page--">上一页</button>{{page}} / {{pages}}<button :disabled="page>=pages" @click="page++">下一页</button></div></section><div v-if="selected" class="overlay" @click.self="selected=null"><section class="dialog" role="dialog" aria-modal="true" aria-label="异常核验详情"><h2>异常核验</h2><p>类型：{{labels[selected.reason_code]??selected.reason_code}}</p><p>被评价人：{{selected.target_name}} · {{selected.department_name??'—'}}</p><h3>处理记录</h3><p v-if="!history.length">暂无处理记录</p><div v-for="(h,index) in history" :key="index" class="history"><strong>{{actions[h.action]??h.action}}</strong> · {{h.actor_name??'系统'}} · {{new Date(h.created_at).toLocaleString()}}<p>{{h.reason}}</p></div><template v-if="selected.status==='OPEN'&&!selected.invalidated_at"><label>核验意见（必填）<textarea v-model.trim="reason" maxlength="500"/></label><div class="dialog-actions"><button class="outline" :disabled="preview||busy||!reason" @click="act('REQUEST_SUPPLEMENT')">退回补充</button><button class="outline" :disabled="preview||busy||!reason" @click="act('DISMISS')">关闭核验项</button><button class="primary" :disabled="preview||busy||!reason" @click="act('CONFIRM')">核验通过</button></div></template><p v-if="error" class="error" role="alert">{{error}}</p><button @click="selected=null">关闭</button></section></div><div v-if="rulesOpen" class="overlay" @click.self="rulesOpen=false"><section class="dialog" role="dialog" aria-modal="true" aria-label="异常规则说明"><h2>异常规则说明</h2><p>系统在周期截止时依据该周期规则对有效他评扫描高分、重点高分、低分指标和高分比例。具体阈值由周期引用的规则决定。</p><p>自他评差异、理由完整性异常和等级目前没有对应的自动检测记录，暂不能显示相关数量。核验不直接修改原评分；反馈申诉在独立模块处理。</p><button @click="rulesOpen=false">关闭</button></section></div></div></template>
<style scoped>
.preview-notice{padding:12px 16px;background:#fff8e8;border:1px solid #f2d79b;color:#805c15;border-radius:8px;margin-bottom:16px}.intro,.bar,.filters,.pagination,.dialog-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.intro{margin-bottom:18px}.intro h2,.panel h2{font-size:19px;margin:0}.intro p,.hint{color:#718099;font-size:13px}.stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-bottom:18px}.stats button,.panel,.dialog{background:#fff;border:1px solid #e1e8f2;border-radius:12px;padding:20px;text-align:left}.stats button span{display:block;color:#728099}.stats strong{display:block;font-size:26px;color:#246bfd;margin-top:8px}.panel{min-width:0}.tabs{display:flex;gap:20px}.tabs button{padding:9px 4px;color:#63738c}.tabs .active{color:#246bfd;border-bottom:2px solid #246bfd}.filters{justify-content:flex-start;margin:18px 0}.filters input,.filters select,.intro select{min-height:36px;border:1px solid #dce4ef;border-radius:6px;padding:6px 10px;background:white}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;white-space:nowrap;padding:13px;border-bottom:1px solid #edf1f7}th{background:#f4f7fc;color:#687890}.badge{background:#edf3ff;color:#246bfd;border-radius:4px;padding:4px 7px}button{cursor:pointer;color:#246bfd;border:0;background:transparent}button:disabled{color:#a4aebc;cursor:not-allowed}.outline{border:1px solid #dce4ef;border-radius:6px;padding:8px 12px}.primary{background:#246bfd;color:white;border-radius:6px;padding:9px 14px}.pagination{justify-content:flex-end;margin-top:16px}.error{color:#b42318}.overlay{position:fixed;inset:0;background:#0006;display:grid;place-items:center;z-index:1000}.dialog{width:min(560px,90vw);max-height:85vh;overflow:auto}.dialog h3{font-size:15px}.dialog textarea{display:block;box-sizing:border-box;width:100%;min-height:90px;margin:10px 0;border:1px solid #dce4ef;border-radius:6px;padding:8px}.history{border-bottom:1px solid #edf1f7;padding:8px 0;font-size:13px}.history p{white-space:pre-wrap}.dialog-actions{justify-content:flex-end;margin:12px 0}@media(max-width:900px){.stats{grid-template-columns:repeat(2,1fr)}}
</style>


